<?php namespace App\Models; use Illuminate\Database\Eloquent\Model; class Applicant extends Model { protected $guarded=[]; protected $casts=['birth_date'=>'date']; public function parent(){return $this->hasOne(ParentData::class,'applicant_id');} public function documents(){return $this->hasMany(Document::class);} public function histories(){return $this->hasMany(StatusHistory::class);} }
